import{_ as r,C as i,o as a,c,a0 as t,b as s,w as o,a as d,E as l,a1 as m}from"./chunks/framework.DYS8d9tm.js";const A=JSON.parse('{"title":"🗄️ Database Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"technical/database/index.md","filePath":"technical/database/index.md"}'),u={name:"technical/database/index.md"};function g(h,e,p,y,_,b){const n=i("Mermaid");return a(),c("div",null,[e[1]||(e[1]=t('<h1 id="🗄️-database-architecture" tabindex="-1">🗄️ Database Architecture <a class="header-anchor" href="#🗄️-database-architecture" aria-label="Permalink to &quot;🗄️ Database Architecture&quot;">​</a></h1><p>WealthFam uses a dual-database design: <strong>PostgreSQL</strong> as the authoritative financial ledger and document metadata repository, and embedded <strong>DuckDB</strong> as the high-performance analytical timeseries database for Admin Studio telemetry and observability. The Parser microservice operates <strong>100% statelessly in memory</strong> with zero tables stored at rest.</p><hr><h2 id="🗺️-logical-relationship-diagram" tabindex="-1">🗺️ Logical Relationship Diagram <a class="header-anchor" href="#🗺️-logical-relationship-diagram" aria-label="Permalink to &quot;🗺️ Logical Relationship Diagram&quot;">​</a></h2><p>WealthFam uses a strict relational structure in PostgreSQL to ensure Precision parentage of every transaction.</p>',5)),(a(),s(m,null,{default:o(()=>[l(n,{id:"mermaid-13",class:"mermaid",graph:"erDiagram%0A%20%20%20%20TENANT%20%7C%7C--o%7B%20USER%20%3A%20contains%0A%20%20%20%20USER%20%7C%7C--o%7B%20ACCOUNT%20%3A%20owns%0A%20%20%20%20ACCOUNT%20%7C%7C--o%7B%20TRANSACTION%20%3A%20tracks%0A%20%20%20%20ACCOUNT%20%7C%7C--o%7B%20POSITION%20%3A%20holds%0A%20%20%20%20USER%20%7C%7C--o%7B%20GOAL%20%3A%20pursues%0A%20%20%20%20GOAL%20%7D%7C--o%7C%20POSITION%20%3A%20linked_to%0A%20%20%20%20GOAL%20%7D%7C--o%7C%20ACCOUNT%20%3A%20linked_to%0A%20%20%20%20TRANSACTION%20%7D%7C--%7C%7C%20CATEGORY%20%3A%20%22classified_as%20(category_id%20FK)%22%0A%20%20%20%20BUDGET%20%7D%7C--o%7C%20CATEGORY%20%3A%20%22targets%20(category_id%20FK)%22%0A%20%20%20%20TRANSACTION%20%7D%7C--o%7C%20LOAN%20%3A%20services%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<hr><h2 id="🏛️-relational-category-normalization-financial-calculation-rules" tabindex="-1">🏛️ Relational Category Normalization &amp; Financial Calculation Rules <a class="header-anchor" href="#🏛️-relational-category-normalization-financial-calculation-rules" aria-label="Permalink to &quot;🏛️ Relational Category Normalization &amp; Financial Calculation Rules&quot;">​</a></h2><p>WealthFam enforces three immutable domain rules across <strong>Backend</strong>, <strong>Web-App</strong>, and <strong>Mobile-App</strong>:</p><ol><li><p><strong>Relational Foreign Key Integrity (<code>category_id</code> FK)</strong>:</p><ul><li>Both <code>transactions</code> and <code>budgets</code> maintain an explicit <code>category_id</code> foreign key (<code>VARCHAR</code>, <code>ON DELETE SET NULL</code>) referencing <code>categories.id</code>, indexed via <code>ix_transactions_tenant_category_id</code> and <code>ix_budgets_tenant_category_id</code> (Alembic revisions <code>g8b9c0d1e2f3</code> and <code>h9c0d1e2f3g4</code>).</li><li>All analytical, budget, merchant, and historical queries join <code>Transaction</code> to <code>Category</code> via <code>Transaction.category_id == Category.id</code> rather than brittle display-string matching. Renaming a category (<code>CategoryService.update_category</code>) atomically cascades canonical names without breaking relational links.</li><li><strong>Zero-Uncategorized Guarantee</strong>: Every active ledger transaction resolves a valid <code>category_id</code> at creation/ingestion time (falling back to the tenant&#39;s <code>&quot;Other&quot;</code> / <code>&quot;General&quot;</code> category of matching type if an unknown label is supplied).</li></ul></li><li><p><strong><code>Category.type</code> as Single Source of Truth</strong>:</p><ul><li>Every transaction&#39;s classification is governed strictly by <code>Category.type</code> (<code>&#39;income&#39;</code>, <code>&#39;expense&#39;</code>, <code>&#39;investment&#39;</code>, <code>&#39;transfer&#39;</code>): <ul><li><strong>Income</strong>: Credits (<code>amount &gt; 0</code>) on categories where <code>Category.type == &#39;income&#39;</code>. Investment redemptions (<code>Category.type == &#39;investment&#39;</code>) and expense refunds (<code>Category.type == &#39;expense&#39;</code>) are never counted as operating income.</li><li><strong>Living Expenses (Net)</strong>: Gross debits (<code>amount &lt; 0</code>) on categories where <code>Category.type == &#39;expense&#39;</code> <strong>minus</strong> positive refunds/credits (<code>amount &gt; 0</code>) on <code>&#39;expense&#39;</code> categories (clamped to $\\ge 0$).</li><li><strong>Investments</strong>: Outflows (<code>amount &lt; 0</code>) on categories where <code>Category.type == &#39;investment&#39;</code>.</li></ul></li></ul></li><li><p><strong>Universal Inclusion Gate &amp; Transfer Symmetry</strong>:</p><ul><li>All reporting, analytics, budget progress, merchant breakdown, and expense group aggregations enforce <code>exclude_from_reports == False</code> and <code>is_transfer == False</code>.</li><li>Any transaction marked <code>is_transfer == True</code> automatically enforces <code>exclude_from_reports = True</code>, resolves the tenant&#39;s canonical <code>&#39;Transfer&#39;</code> category (<code>category_id</code> and <code>category = &#39;Transfer&#39;</code>), and maintains bidirectional counterpart symmetry (<code>linked_transaction_id</code>) across creation, updates, pairing, unpairing, and soft-deletion.</li></ul></li></ol><hr><h2 id="🏗️-core-schemas" tabindex="-1">🏗️ Core Schemas <a class="header-anchor" href="#🏗️-core-schemas" aria-label="Permalink to &quot;🏗️ Core Schemas&quot;">​</a></h2><h3 id="⚙️-backend-schema" tabindex="-1">⚙️ <a href="https://github.com/WealthFam/Docs/blob/main/technical/database/backend_schema.sql" target="_blank" rel="noreferrer">Backend Schema</a> <a class="header-anchor" href="#⚙️-backend-schema" aria-label="Permalink to &quot;⚙️ [Backend Schema](https://github.com/WealthFam/Docs/blob/main/technical/database/backend_schema.sql)&quot;">​</a></h3><p>The primary ledger and product metadata schema in PostgreSQL:</p><ul><li>High-concurrency transaction and account tables (<code>transactions</code>, <code>accounts</code>, <code>statements</code>).</li><li>Cross-source deduplication indices (<code>content_hash</code>, <code>external_id</code>).</li><li>Ingestion audit logs (<code>ingestion_events</code>, <code>email_sync_item_logs</code>).</li><li>Document Vault storage metadata (<code>document_vault</code>, <code>document_versions</code>).</li><li>Tenant-scoped merchant normalization rules (<code>merchant_aliases</code>).</li><li>Mutual Fund holdings and intelligence records (<code>mutual_fund_holdings</code>, <code>mutual_fund_orders</code>, <code>mutual_fund_sips</code>, <code>mutual_fund_constituents</code>, <code>mutual_fund_benchmarks</code>).</li></ul><h3 id="🔄-stateless-parser-engine-0-tables-at-rest" tabindex="-1">🔄 Stateless Parser Engine (0 Tables at Rest) <a class="header-anchor" href="#🔄-stateless-parser-engine-0-tables-at-rest" aria-label="Permalink to &quot;🔄 Stateless Parser Engine (0 Tables at Rest)&quot;">​</a></h3><p>The Financial Parser Microservice is completely stateless. It performs zero database writes during runtime:</p><ul><li>Network idempotency is secured via an in-memory 5-minute sliding LRU cache (<code>RecentSubmissionCache</code>).</li><li>Bank rules are compiled Python parsers in <code>Parser/parsers/bank/</code>.</li><li>Financial deduplication is delegated to PostgreSQL&#39;s <code>TransactionDeduplicator</code>.</li><li>Telemetry metrics are streamed asynchronously to Admin DuckDB.</li></ul><h3 id="🛡️-critical-pattern-json-jsonb-array-handling" tabindex="-1">🛡️ Critical Pattern: JSON/JSONB Array Handling <a class="header-anchor" href="#🛡️-critical-pattern-json-jsonb-array-handling" aria-label="Permalink to &quot;🛡️ Critical Pattern: JSON/JSONB Array Handling&quot;">​</a></h3><p>For columns storing JSON arrays (like <code>CategoryRule.keywords</code>), the backend uses PostgreSQL&#39;s native <code>JSONB</code> column type.</p><ul><li>WealthFam enforces a <strong>Safe Deserialization Pattern</strong>: keywords are deserialized using a validation helper (<code>RuleExecutor._parse_keywords</code>), which correctly handles both Python list types and serialized JSON string types (e.g. <code>&#39;[&quot;KEYWORD&quot;]&#39;</code>) returned by the database.</li><li>Keyword validation and formatting are performed strictly before transactions are committed to ensure DB constraints are satisfied.</li></ul><hr><h2 id="🗄️-why-this-dual-database-design" tabindex="-1">🗄️ Why this Dual-Database Design? <a class="header-anchor" href="#🗄️-why-this-dual-database-design" aria-label="Permalink to &quot;🗄️ Why this Dual-Database Design?&quot;">​</a></h2><h3 id="🐘-postgresql-backend" tabindex="-1">🐘 PostgreSQL (Backend) <a class="header-anchor" href="#🐘-postgresql-backend" aria-label="Permalink to &quot;🐘 PostgreSQL (Backend)&quot;">​</a></h3><p>PostgreSQL handles the core system ledger (<code>transactions</code>, <code>accounts</code>, <code>statements</code>), Document Vault metadata (<code>document_vault</code>, <code>document_versions</code>, backed on disk by persistent <code>VAULT_STORAGE_PATH=/data/vault</code> with automatic startup path self-healing), multi-user tenant partitioning, ingestion audit logs (<code>ingestion_events</code>, <code>email_sync_item_logs</code> storing full <code>raw_content</code>, <code>outcome</code>, and <code>details_json</code>), user filter rules (<code>spam_filters</code> covering <code>SMS</code>, <code>EMAIL</code>, <code>STATEMENT</code>, and <code>ALL</code>; plus <code>ignored_patterns</code>), and tenant-scoped <code>merchant_aliases</code>. It provides ACID concurrency, standard indices, and startup/Alembic schema management.</p><h3 id="🦆-duckdb-admin-telemetry-timeseries-control-plane" tabindex="-1">🦆 DuckDB (Admin Telemetry Timeseries &amp; Control Plane) <a class="header-anchor" href="#🦆-duckdb-admin-telemetry-timeseries-control-plane" aria-label="Permalink to &quot;🦆 DuckDB (Admin Telemetry Timeseries &amp; Control Plane)&quot;">​</a></h3><p>DuckDB powers the Admin telemetry and observability control plane (<code>data/telemetry.duckdb</code>), served from the root <code>data/</code> volume (<code>/data/</code> in Docker):</p><ul><li><strong>Stateless Parser</strong>: The Parser microservice is <strong>100% stateless and code-driven</strong> using compiled Python parsers and an in-memory thread-safe submission cache (<code>RecentSubmissionCache</code>). It does not persist financial PII or write request logs to disk, completely eliminating DuckDB lock contention during high-concurrency ingestion batches. Scrubbed extraction metrics are shipped asynchronously to <code>Admin-Backend</code>.</li><li><strong>Admin Telemetry (<code>telemetry.duckdb</code>)</strong>: Anonymous API latency percentiles (<code>telemetry_api_metrics</code>), parser extraction telemetry (<code>telemetry_parser_events</code>), mobile/web client telemetry (<code>telemetry_client_events</code>), PII-scrubbed logs (<code>telemetry_system_logs</code>), 30s health probes (<code>endpoint_health_checks</code>), consented format-preserved <code>telemetry_training_samples</code>, and <code>admin_users</code>.</li><li><strong>Brand Assets (<code>data/logos/</code> + PostgreSQL <code>brand_logos</code>)</strong>: Individual brand icon files reside in <code>data/logos/</code> while metadata and matching regexes live in PostgreSQL (<code>brand_logos</code> with an offline DuckDB mirror).</li></ul><hr><div align="center"> *Precision Ledger · Columnar Performance · Privacy First* </div>',24))])}const C=r(u,[["render",g]]);export{A as __pageData,C as default};
